import {normalize,shuffle,localDate,reviewAnswer,isMastered,isDue,vocabularyQuestion,selectWords,coverage,validProgress,meaningsOverlap} from './core.js';
import {mountHomeMotion,getTheme,toggleTheme} from './appearance.js?v=3';

const AREAS={morphology:{name:'Morfologia',symbol:'λ',number:'01',description:'Reconheça as formas. Aprenda os padrões que dão estrutura a cada palavra.',focus:'Padrões, paradigmas e parsing',short:'Formas que fazem sentido'},syntax:{name:'Sintaxe',symbol:'σ',number:'02',description:'Conecte as palavras. Entenda como cada termo participa da construção do sentido.',focus:'Conceitos, relações e contexto',short:'Das palavras ao sentido'},vocabulary:{name:'Vocabulário',symbol:'ω',number:'03',description:'Amplie seu repertório. Memorize os vocábulos e encontre-os de novo no texto.',focus:'Memorização com revisão espaçada',short:'Um repertório para ler'}};
const LEVELS=['Fundamentos','Essencial','Aprofundamento','Avançado'];
const LEVEL_DESCRIPTIONS=['Seu primeiro contato, com conceitos e exemplos guiados.','Consolide os padrões e relações mais frequentes.','Reconheça construções mais complexas e amplie sua autonomia.','Compare análises, enfrente ambiguidades e leia criticamente.'];
const STORAGE=`koine-study-v1:${new URL('.',document.baseURI).pathname}`;
const blank=()=>({version:1,levels:{morphology:0,syntax:0,vocabulary:0},lessons:{},vocab:{},answers:{},sessions:0});
let state=blank(),storageAvailable=true;
try { const stored=JSON.parse(localStorage.getItem(STORAGE)); if(validProgress(stored))state={...blank(),...stored}; } catch {storageAvailable=false;}
let lessons=[],vocabulary={meta:{},entries:[]},session=null,searchOpen=false,searchTerm='',vocabSearch='',vocabFilter='all',vocabClass='all',vocabPage=0,menuOpen=false,toastTimer;
const app=document.querySelector('#app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=new Intl.NumberFormat('pt-BR');
const pct=value=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(value);
const icons={sun:'M12 3v2 M12 19v2 M3 12h2 M19 12h2 M5.6 5.6 7 7 M17 17l1.4 1.4 M5.6 18.4 7 17 M17 7l1.4-1.4 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M20.3 15.4A9 9 0 0 1 8.6 3.7 9 9 0 1 0 20.3 15.4Z',home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',morphology:'M5 4h14v16H5z M9 8h6 M9 12h6 M9 16h3',syntax:'M12 3v6 M5 21v-6h14v6 M5 15V9h14v6 M9 3h6',vocabulary:'M4 4h6a4 4 0 0 1 4 4v13a4 4 0 0 0-4-3H4z M14 8a4 4 0 0 1 4-4h3v14h-3a4 4 0 0 0-4 3',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',progress:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',cards:'M6 3h14v17H6z M3 7v16h13',practice:'m13 2-8 12h6l-1 8 9-13h-6z',path:'M6 4a2 2 0 1 0 0 .1 M18 20a2 2 0 1 0 0 .1 M8 4h6a4 4 0 0 1 0 8h-4a4 4 0 0 0 0 8h6',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',book:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',menu:'M3 6h18 M3 12h18 M3 18h18',leaf:'M20 3C7 2 2 8 5 15s13 6 15-12Z M5 20 15 9'};
const icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
const route=()=>location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);
const goto=path=>{menuOpen=false;searchOpen=false;session=null;if(location.hash===`#/${path}`)render();else location.hash=`/${path}`;};
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{if(storageAvailable)toast('O navegador não permitiu salvar. Exporte seu progresso para preservá-lo.');storageAvailable=false;}}
function toast(message){clearTimeout(toastTimer);document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.append(el);toastTimer=setTimeout(()=>el.remove(),5500);}
const progress=(value,max)=>`<div class="progress-track" role="progressbar" aria-label="Progresso" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${value}"><div class="progress-fill" style="width:${max?Math.min(value/max*100,100):0}%"></div></div>`;
const areaLessons=(area,level=null)=>lessons.filter(l=>l.area===area&&(level===null||l.level===level)).sort((a,b)=>a.order-b.order);
const completed=(area)=>areaLessons(area).filter(l=>state.lessons[l.id]).length;
const mastered=()=>vocabulary.entries.filter(w=>isMastered(state.vocab[w.id]));
const coreMastered=()=>mastered().filter(w=>w.core300).length;
const tokenCount=()=>vocabulary.meta.frequency?.tokens||0;
const levelWords=area=>vocabulary.entries.filter(w=>w.level===state.levels[area]);

function formationArtwork(area,compact=false){
 const common='viewBox="0 0 360 158" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"';
 if(area==='morphology')return `<svg ${common}><path d="M32 113h296M32 45h296" stroke="#235b61"/><rect x="34" y="55" width="108" height="52" rx="3" stroke="#59ddba" stroke-width="2"/><rect x="165" y="55" width="64" height="52" rx="3" stroke="#59ddba" stroke-width="2"/><rect x="252" y="55" width="64" height="52" rx="3" stroke="#59ddba" stroke-width="2"/><g fill="#d5fff1" font-family="Georgia,serif" text-anchor="middle" font-size="32"><text x="88" y="90">λογ</text><text x="197" y="90">ο</text><text x="284" y="90">ς</text></g><g fill="#8ebeb2" font-family="Arial,sans-serif" font-size="10" text-anchor="middle"><text x="88" y="133">RADICAL</text><text x="197" y="133">VOGAL</text><text x="284" y="133">TERMINAÇÃO</text></g><g stroke="#59ddba"><path d="M148 81h11m-5-5v11M235 81h11m-5-5v11"/></g></svg>`;
 if(area==='syntax')return `<svg ${common}><path d="M48 37h264M48 120h264" stroke="#244e7e"/><g fill="#dbeaff" font-family="Georgia,serif" font-size="29"><text x="53" y="78">ὁ μαθητὴς</text><text x="228" y="78">γράφει</text></g><path d="M53 91h139m36 0h81M122 92v13h145V92" stroke="#63adff" stroke-width="2"/><g fill="#89b8f2" font-family="Arial,sans-serif" font-size="10"><text x="100" y="136">SUJEITO</text><text x="250" y="136">VERBO</text></g></svg>`;
 return `<svg ${common}><rect x="47" y="29" width="266" height="102" rx="3" stroke="#dfab65"/><path d="M47 91h266" stroke="#715937"/><text x="180" y="73" text-anchor="middle" fill="#fff2dc" font-family="Georgia,serif" font-size="35">λόγος</text><text x="180" y="116" text-anchor="middle" fill="#e6c292" font-family="Arial,sans-serif" font-size="12">palavra · mensagem · discurso</text><path d="M35 44V17h29m261 99v27h-29" stroke="#c29253"/></svg>`;
}
function shell(content,active='home',crumb='Meus estudos'){
 const navLinks=`<a href="#/home" class="${active==='home'?'active':''}" ${active==='home'?'aria-current="page"':''}>Início</a>${Object.entries(AREAS).map(([key,a])=>`<a href="#/${key}/path" class="${active===key?'active':''}" ${active===key?'aria-current="page"':''}>${a.name}</a>`).join('')}`;
 const themeLabel=getTheme()==='dark'?'Ativar modo claro':'Ativar modo noturno';
 return `<div class="layout" data-area="${active}"><header class="site-header"><div class="header-inner"><a class="wordmark" href="#/home" aria-label="Koiné, início"><span class="brand-name">koiné<span class="brand-dot">.</span></span></a><div class="nav-container ${menuOpen?'open':''}"><nav class="main-nav" aria-label="Navegação principal">${navLinks}<a class="nav-about ${active==='about'?'active':''}" href="#/about">O projeto</a><a class="mobile-progress" href="#/progress">Meu progresso</a></nav></div><div class="header-tools"><button class="header-search search-toggle header-tool" data-action="search" aria-label="Buscar no conteúdo" title="Buscar no conteúdo">${icon('search',19)}</button><button class="theme-toggle header-tool" data-action="theme" aria-label="${themeLabel}" title="${themeLabel}">${icon(getTheme()==='dark'?'sun':'moon',19)}</button><a class="header-progress header-tool ${active==='progress'?'active':''}" href="#/progress" aria-label="Meu progresso" title="Meu progresso">${icon('progress',19)}</a><button class="menu-toggle header-tool" data-action="menu" aria-label="Abrir navegação" aria-expanded="${menuOpen}">${icon(menuOpen?'close':'menu',23)}</button></div></div></header>${menuOpen?'<button class="nav-backdrop" data-action="close-menu" aria-label="Fechar navegação"></button>':''}<div class="workspace"><div class="topbar"><div class="breadcrumbs"><a href="#/home">Início</a><span>/</span><strong>${esc(crumb)}</strong></div><span class="local-tag">${icon('check',13)}${storageAvailable?'Seu progresso é salvo neste navegador':'Salvamento indisponível'}</span></div><main id="main" class="content area-${active}" tabindex="-1">${content}</main><footer class="page-footer"><a class="footer-wordmark" href="#/home">koiné.</a><span>Projeto de <a href="https://github.com/LaylsondeAlbuquerque" target="_blank" rel="noopener">Laylson de Albuquerque</a></span><a href="#/about">Fontes, licenças e metodologia</a><span class="footer-note">Estudo aberto e gratuito</span></footer></div></div>`;
}

function formationCard(key){
 const a=AREAS[key],list=areaLessons(key),count=key==='vocabulary'?mastered().length:completed(key),total=key==='vocabulary'?vocabulary.entries.length:list.length;
 const description={morphology:'Alfabeto, declinações, pronomes e sistema verbal. Aprenda a reconhecer e analisar as formas.',syntax:'Casos, funções e construções. Entenda as relações da oração e compare abordagens.',vocabulary:'Estude os lemas por frequência, pratique as traduções e organize suas revisões.'}[key];
 return `<a class="formation-card ${key}" href="#/${key}/path"><div class="formation-cover">${formationArtwork(key)}</div><div class="formation-body"><span class="formation-type">FORMAÇÃO</span><h3>${a.name}</h3><p>${description}</p><div class="course-meta">${icon('book',14)}${list.length} artigos<span>·</span>${key==='vocabulary'?`${fmt.format(total)} vocábulos`:'4 níveis'}</div><div class="formation-progress-label"><span>${key==='vocabulary'?'Memorização':'Leitura do conteúdo'}</span><strong>${Math.round(count/total*100)}%</strong></div>${progress(count,total)}</div><div class="formation-footer"><span>Ver formação</span>${icon('arrow',16)}</div></a>`;
}
function home(){
 const allRead=lessons.filter(l=>state.lessons[l.id]).length;
 const first=lessons.find(l=>l.area==='morphology'&&!state.lessons[l.id])||areaLessons('morphology')[0];
 const due=vocabulary.entries.filter(w=>isDue(state.vocab[w.id])).length;
 const picks=[lessons.find(l=>l.id==='m-artigo'),areaLessons('syntax',0)[0],areaLessons('vocabulary',0)[1],areaLessons('syntax',3)[0]].filter(Boolean);
 return shell(`<div class="home-flow"><section class="home-hero" aria-labelledby="home-title"><canvas id="home-motion" aria-hidden="true"></canvas><div class="hero-atmosphere" aria-hidden="true"></div><div class="hero-copy"><p class="hero-kicker">GREGO KOINÉ · ESTUDO ABERTO</p><h1 id="home-title">Aprenda grego.<br><span>Leia o Novo Testamento.</span></h1><p class="hero-description">Morfologia, sintaxe e vocabulário.<br>Um percurso do alfabeto à análise do texto.</p><div class="hero-actions"><a class="button hero-start" href="#/morphology/article/${first.id}">${allRead?'Continuar estudando':'Começar a estudar'}<span>${icon('arrow',19)}</span></a><button class="hero-explore" data-action="explore">Conhecer as formações${icon('arrow',16)}</button></div></div><div class="hero-bottom"><span>${lessons.length} artigos <i></i>${lessons.reduce((n,l)=>n+l.questions.length,0)} exercícios <i></i>${fmt.format(vocabulary.entries.length)} vocábulos</span><button class="motion-toggle" data-motion-toggle aria-label="Pausar animação" aria-pressed="false"><span aria-hidden="true">Ⅱ</span><span>Pausar animação</span></button></div></section><section class="home-section home-formations" id="formacoes"><div class="section-heading"><div><p class="section-kicker">ESCOLHA SEU PERCURSO</p><h2>Três formas de avançar<br>na mesma língua.</h2></div><p class="section-intro">Comece pelos fundamentos ou vá direto ao seu nível. Cada formação reúne explicações e atividades para praticar.</p></div><div class="formation-grid">${Object.keys(AREAS).map(formationCard).join('')}</div></section><section class="home-section"><div class="study-resume"><div class="resume-label">${allRead?'SEU PRÓXIMO PASSO':'PRIMEIRA AULA'}</div><div class="resume-main"><span>${AREAS[first.area].name} · ${LEVELS[first.level]} · ${first.minutes} min</span><h2>${esc(first.title)}</h2><p>${esc(first.summary)}</p></div><a class="button button-primary" href="#/${first.area}/article/${first.id}">${allRead?'Continuar aula':'Estudar agora'}${icon('arrow',17)}</a></div></section><section class="home-section home-practice"><div class="section-heading"><div><p class="section-kicker">DA LEITURA À PRÁTICA</p><h2>Aprenda. Experimente.<br>Volte ao texto.</h2></div><p class="section-intro">Reconheça uma forma, entenda uma relação, recorde uma palavra. Pratique com respostas e explicações imediatas.</p></div><div class="quick-grid"><a class="quick-card morphology" href="#/morphology/practice"><span class="quick-icon">${icon('morphology',26)}</span><span><strong>Parsing e paradigmas</strong><small>Identifique as formas das palavras</small></span>${icon('arrow',18)}</a><a class="quick-card syntax" href="#/syntax/practice"><span class="quick-icon">${icon('syntax',26)}</span><span><strong>Funções na oração</strong><small>Relacione os termos e suas funções</small></span>${icon('arrow',18)}</a><a class="quick-card vocabulary" href="#/vocabulary/practice"><span class="quick-icon">${icon('cards',26)}</span><span><strong>Palavras e traduções</strong><small>Associe vocábulos aos seus sentidos</small></span>${icon('arrow',18)}</a></div></section><section class="home-section home-library"><div class="section-heading"><div><p class="section-kicker">PARA EXPLORAR</p><h2>Entre no assunto.</h2></div><a class="text-link" href="#/morphology/articles">Todos os artigos${icon('arrow',16)}</a></div><div class="discovery-grid">${picks.map(l=>`<a class="discovery-card ${l.area}" href="#/${l.area}/article/${l.id}"><div class="discovery-top">${icon(l.area,24)}<span>${AREAS[l.area].name}</span></div><h3>${esc(l.title)}</h3><p>${LEVELS[l.level]}</p><div class="discovery-meta">${icon('clock',13)}${l.minutes} min de leitura${icon('arrow',15)}</div></a>`).join('')}</div></section><section class="home-section"><div class="home-priority"><div><p class="section-kicker">SEU NÚCLEO DE VOCABULÁRIO</p><h2>As 300 palavras<br>que mais aparecem.</h2><p>${coreMastered()} de 300 memorizadas · ${pct(vocabulary.meta.core300?.coveragePercent||0)}% das ocorrências no corpus utilizado.</p></div><div class="priority-action"><a class="button hero-start" href="#/vocabulary/words">Explorar vocabulário<span>${icon('arrow',18)}</span></a><p>${due?`${due} vocábulos para revisar hoje.`:'Memorização com revisão em dias diferentes.'}</p></div></div></section></div>`);
}

function areaHeader(area,tab){
 const a=AREAS[area],level=state.levels[area],list=areaLessons(area);
 return `<header class="formation-heading ${area}"><div class="formation-heading-icon">${icon(area,32)}</div><div><div class="eyebrow">FORMAÇÃO · GREGO KOINÉ</div><h1>${a.name}</h1><p>${esc(a.focus)}</p><div class="formation-info"><span>${icon('book',14)}${list.length} artigos</span><span>${icon('path',14)}4 níveis</span><span>${icon('practice',14)}${list.reduce((n,l)=>n+l.questions.length,0)} exercícios</span>${area==='vocabulary'?`<span>${fmt.format(vocabulary.entries.length)} vocábulos</span>`:''}</div></div></header><div class="level-bar"><span>Selecione seu nível</span><div class="level-buttons" aria-label="Escolher nível">${LEVELS.map((name,i)=>`<button class="level-button ${level===i?'active':''}" data-action="level" data-area="${area}" data-level="${i}" aria-pressed="${level===i}"><span class="level-no">${i+1}</span>${name}</button>`).join('')}</div></div><nav class="tabs" aria-label="Modos de estudo">${[['path','Percurso','path'],['articles','Artigos','book'],['flashcards','Flashcards','cards'],['practice','Prática','practice'],...(area==='vocabulary'?[['words','Repertório','vocabulary']]:[])].map(([key,title,i])=>`<a href="#/${area}/${key}" class="tab ${tab===key?'active':''}" ${tab===key?'aria-current="page"':''}>${icon(i,17)}${title}</a>`).join('')}</nav>`;
}

function areaPage(area,tab='path'){
 let body='';const level=state.levels[area],current=areaLessons(area,level);
 if(tab==='path')body=`<div class="level-summary"><div><h2>${LEVELS[level]}</h2><p>${LEVEL_DESCRIPTIONS[level]}</p></div><span class="pill">${current.length} ${current.length===1?'unidade':'unidades'}</span></div><div class="lesson-list">${current.map((l,i)=>`<article class="lesson-row"><div class="lesson-step ${state.lessons[l.id]?'done':''}">${state.lessons[l.id]?icon('check',15):String(i+1).padStart(2,'0')}</div><div><h3><a href="#/${area}/article/${l.id}">${esc(l.title)}</a></h3><p>${esc(l.summary)}</p><div class="lesson-row-meta">${icon('clock',11)}${l.minutes} min<span>·</span>${l.questions.length} exercícios${state.lessons[l.id]?'<span>· Leitura concluída</span>':''}</div></div><div class="lesson-row-actions"><button class="text-link" data-action="start" data-area="${area}" data-lesson="${l.id}" data-mode="practice">Praticar</button><a class="button button-outline button-small" href="#/${area}/article/${l.id}">Estudar${icon('arrow',12)}</a></div></article>`).join('')}</div>${level<3?`<div class="notice">Cada nível fica disponível desde o início. Quando se sentir confortável, avance para <button class="text-link" data-action="level" data-area="${area}" data-level="${level+1}">${LEVELS[level+1]} ${icon('arrow',12)}</button>.</div>`:''}`;
 else if(tab==='articles')body=`<div class="level-summary"><div><h2>Artigos deste nível</h2><p>Explicações, exemplos e conexões para ${LEVELS[level].toLowerCase()}.</p></div><span class="pill">${current.length} artigos</span></div><div class="article-grid">${current.map(l=>`<a class="article-card" href="#/${area}/article/${l.id}"><span class="eyebrow">${LEVELS[level]} · ${l.minutes} min</span><h3>${esc(l.title)}</h3><p>${esc(l.summary)}</p><span class="pill ${state.lessons[l.id]?'':'lilac'}">${state.lessons[l.id]?'Leitura concluída':`${l.questions.length} exercícios para fixar`}</span><span class="text-link">Ler artigo${icon('arrow',13)}</span></a>`).join('')}</div>`;
 else if(tab==='words'&&area==='vocabulary')body=wordRepertory();
 else body=studyLanding(area,tab);
 return shell(areaHeader(area,tab)+body,area,AREAS[area].name);
}
function paragraphs(body){return String(body??'').split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');}
function tableHTML(table){if(!table)return '';return `<div class="table-wrap"><table><thead><tr>${table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr>${row.map(cell=>`<td ${/[\u0370-\u03ff\u1f00-\u1fff]/.test(cell)?'class="greek" lang="grc"':''}>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function articlePage(area,id){const l=lessons.find(x=>x.id===id&&x.area===area);if(!l)return shell(empty('Artigo não encontrado','Volte ao percurso para escolher um artigo.'),area,AREAS[area].name);const collection=areaLessons(area);const next=collection[collection.indexOf(l)+1];return shell(`<a class="back-link" href="#/${area}/path">${icon('back',14)}Voltar ao percurso de ${AREAS[area].name.toLowerCase()}</a><div class="article-layout"><article><header class="article-head"><span class="eyebrow">${AREAS[area].name} · ${LEVELS[l.level]} · ${l.minutes} min</span><h1>${esc(l.title)}</h1><p class="summary">${esc(l.summary)}</p></header>${l.sections.map(s=>`<section class="article-section"><h2>${esc(s.heading)}</h2>${paragraphs(s.body)}${tableHTML(s.table)}</section>`).join('')}${l.examples?.length?`<section class="article-section"><h2>Observe no exemplo</h2>${l.examples.map(e=>`<div class="example-box"><span class="greek" lang="grc">${esc(e.greek)}</span><p class="translation">${esc(e.translation)}</p><p class="note">${esc(e.note)}</p></div>`).join('')}</section>`:''}<div class="references"><h3>Referências e abordagem</h3><ul>${l.references.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><p>Texto didático original. As fontes orientam a análise; não constituem reprodução das obras.</p></div><div class="session-actions"><button class="button button-primary" data-action="start" data-area="${area}" data-lesson="${l.id}" data-mode="practice">Praticar este conceito${icon('arrow',14)}</button>${next?`<a href="#/${area}/article/${next.id}" class="text-link">Próximo artigo${icon('arrow',13)}</a>`:''}</div></article><aside class="article-aside"><span class="eyebrow">Aprender com intenção</span><h3 class="objectives-label" style="margin-top:14px">Ao final, você poderá</h3><ul>${l.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><h3>${l.questions.length} exercícios de fixação</h3><button class="button button-primary" data-action="start" data-area="${area}" data-lesson="${l.id}" data-mode="practice">Praticar${icon('practice',13)}</button><button class="button button-outline" data-action="read" data-lesson="${l.id}" aria-pressed="${Boolean(state.lessons[l.id])}">${icon(state.lessons[l.id]?'check':'book',13)}${state.lessons[l.id]?'Leitura concluída':'Concluir leitura'}</button></aside></div>`,area,`${AREAS[area].name} / Artigo`);}
function empty(title,message){return `<div class="empty-state"><h2>${esc(title)}</h2><p>${esc(message)}</p></div>`;}
function studyLanding(area,mode){const flash=mode==='flashcards',vocab=area==='vocabulary',count=vocab?levelWords(area).length:areaLessons(area,state.levels[area]).reduce((n,l)=>n+l.questions.filter(q=>!flash||['choice','parse'].includes(q.kind)).length,0);return `<div class="study-landing"><section class="study-start"><div class="study-glyph" lang="grc">${vocab?'λέξις':area==='morphology'?'λύω':'σύν'}</div><span class="eyebrow">${LEVELS[state.levels[area]]} · ${flash?'Reconhecer e recordar':'Aplicar o que você aprendeu'}</span><h2 style="margin-top:12px">${flash?'Flashcards':vocab?'Associação de vocábulos':area==='morphology'?'Prática de morfologia':'Prática de sintaxe'}</h2><p>${flash?'Selecione uma resposta e receba uma explicação imediata. Cada reencontro ajuda a consolidar o que você estudou.':vocab?'Relacione vocábulos a suas glossas e pratique a identificação de sentidos. As revisões seguem seu histórico neste navegador.':area==='morphology'?'Pratique parsing, associe formas aos seus traços e reconheça paradigmas. Todas as respostas são feitas por seleção.':'Identifique funções, relacione conceitos e organize traduções didáticas. O contexto e a explicação acompanham cada resposta.'}</p><div class="study-settings"><label class="field">Tamanho da sessão<select id="session-size"><option value="10">10 exercícios</option><option value="5">5 exercícios</option><option value="20">20 exercícios</option></select></label>${vocab?`<label class="field">Escolher vocábulos<select id="session-filter"><option value="level">Deste nível · ${count} vocábulos</option><option value="core">Núcleo dos 300 · todos os níveis</option><option value="due">Revisões de hoje · todos os níveis</option><option value="all">Repertório completo</option><option value="new">Ainda não estudados · todos os níveis</option></select></label>`:`<label class="field">Assunto<select id="session-lesson"><option value="">Todos os assuntos deste nível</option>${areaLessons(area,state.levels[area]).map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('')}</select></label>`}</div><button class="button button-primary" data-action="start" data-area="${area}" data-mode="${mode}">Começar sessão${icon('arrow',15)}</button></section><aside class="study-tips"><span class="eyebrow">Um jeito de estudar melhor</span>${[[flash?'Pense antes de selecionar':'Observe antes de responder',flash?'Tente recordar o sentido ou a análise antes de olhar as alternativas.':'Leia o trecho inteiro. A mesma forma pode ter possibilidades diferentes.'],['Use a explicação','Um erro é uma pista: volte ao padrão ou conceito que ainda precisa de atenção.'],[vocab?'Volte em dias diferentes':'Conecte teoria e prática',vocab?'A memorização é registrada após acertos em três dias diferentes. Erros devolvem o vocábulo à revisão.':'Leia o artigo quando precisar. O percurso permanece aberto para você retornar.']].map(([title,text],i)=>`<div class="tip-row"><span class="tip-num">0${i+1}</span><div><strong>${title}</strong>${text}</div></div>`).join('')}<div class="notice">${vocab?'As glossas são apoios de memória. O contexto da passagem determina a tradução adequada.':`${count} exercícios disponíveis neste nível. As sessões variam as questões e a ordem das alternativas.`}</div></aside></div>`;}

function wordRepertory(){const total=vocabulary.entries.length;return `<section class="vocab-banner"><div><div class="eyebrow" style="color:#b7cbaa">SEU NÚCLEO DE LEITURA</div><h2>300 palavras, muitos reencontros.</h2><p>Os 300 lemas mais frequentes deste repertório somam ${pct(vocabulary.meta.core300?.coveragePercent||0)}% das ocorrências do corpus. Isso mede cobertura lexical; interpretar o texto também exige morfologia, sintaxe e contexto.</p></div><div class="core-count">${coreMastered()} <span>/ 300 memorizados</span></div></section><div class="level-summary"><div><h2>Seu repertório completo</h2><p>${fmt.format(total)} vocábulos · lista independente por frequência, com consulta ao repertório de Porter.</p></div><button class="text-link" data-action="start" data-area="vocabulary" data-mode="flashcards" data-core="true">Estudar os 300${icon('arrow',13)}</button></div><div class="vocab-toolbar"><label class="search-field">${icon('search',16)}<span class="sr-only">Buscar vocábulo ou tradução</span><input id="vocab-search" type="search" value="${esc(vocabSearch)}" placeholder="Buscar em grego ou português, com ou sem acentos…"></label><label><span class="sr-only">Filtrar repertório</span><select id="vocab-filter">${[['all','Todos os vocábulos'],['core','Núcleo dos 300'],['new','Ainda não estudados'],['due','Para revisar hoje'],['mastered','Memorizados']].map(([v,n])=>`<option value="${v}" ${vocabFilter===v?'selected':''}>${n}</option>`).join('')}</select></label><label><span class="sr-only">Classe gramatical</span><select id="vocab-class"><option value="all">Todas as classes</option>${[...new Set(vocabulary.entries.map(w=>w.pos))].sort().map(pos=>`<option value="${esc(pos)}" ${vocabClass===pos?'selected':''}>${esc(pos)}</option>`).join('')}</select></label></div><div id="word-results">${wordResults()}</div>`;}
function filteredWords(){const query=normalize(vocabSearch);return vocabulary.entries.filter(w=>(!query||normalize(`${w.lemma} ${w.meaning} ${(w.aliases||[]).join(' ')}`).includes(query))&&(vocabClass==='all'||w.pos===vocabClass)&&(vocabFilter!=='core'||w.core300)&&(vocabFilter!=='mastered'||isMastered(state.vocab[w.id]))&&(vocabFilter!=='due'||isDue(state.vocab[w.id]))&&(vocabFilter!=='new'||!state.vocab[w.id]));}
function wordResults(){const words=filteredWords(),pages=Math.ceil(words.length/48);vocabPage=Math.min(vocabPage,Math.max(pages-1,0));return `${words.length?`<p class="muted" style="font-size:9px;margin-bottom:13px">${fmt.format(words.length)} ${words.length===1?'vocábulo encontrado':'vocábulos encontrados'}</p><div class="vocab-grid">${words.slice(vocabPage*48,(vocabPage+1)*48).map(w=>{const s=state.vocab[w.id];return `<button class="word-card" data-action="word" data-word="${w.id}" aria-label="Estudar ${esc(w.lemma)}"><span class="word-top"><span class="word-rank">#${String(w.rank).padStart(3,'0')}</span>${w.core300?'<span class="pill amber">Núcleo dos 300</span>':''}</span><span class="greek" lang="grc">${esc(w.lemma)}</span><span class="word-meaning">${esc(w.meaning)}</span><span class="word-bottom"><span>${esc(w.pos)} · ${fmt.format(w.frequency)} ocorr.</span><span class="word-state" aria-label="${Math.min(s?.dates?.length||0,3)} de 3 dias com acertos">${[0,1,2].map(i=>`<i class="${(s?.dates?.length||0)>i?'filled':''}"></i>`).join('')}</span></span></button>`;}).join('')}</div>`:empty('Nenhum vocábulo neste filtro','Tente outro termo ou altere os filtros.')} ${pages>1?`<div class="pagination"><button class="button button-outline button-small" data-action="page" data-page="${vocabPage-1}" ${vocabPage===0?'disabled':''}>${icon('back',12)}Anterior</button><span>Página ${vocabPage+1} de ${pages}</span><button class="button button-outline button-small" data-action="page" data-page="${vocabPage+1}" ${vocabPage+1>=pages?'disabled':''}>Próxima${icon('arrow',12)}</button></div>`:''}`;}

function prepareQuestion(question,lesson){let q=JSON.parse(JSON.stringify(question));q.lessonId=lesson?.id;q.lessonTitle=lesson?.title;if(q.kind==='choice'){const options=shuffle(q.options.map((text,index)=>({text,index})));q.options=options.map(o=>o.text);q.answer=options.findIndex(o=>o.index===q.answer);}if(q.kind==='match'){q.rightOrder=shuffle(q.pairs.map((_,i)=>i));}if(q.kind==='order'){q.tokenOrder=shuffle(q.tokens.map((_,i)=>i));}return q;}
function parsingCard(q,l){const good=q.fields.map(f=>`${f.label}: ${f.answer}`).join(' · ');const variants=q.fields.map((f,i)=>{const alt=f.options.find(x=>x!==f.answer);if(!alt)return null;return q.fields.map((ff,j)=>`${ff.label}: ${j===i?alt:ff.answer}`).join(' · ');}).filter(Boolean);const options=shuffle([good,...shuffle(variants).slice(0,3)]);return {...q,kind:'choice',options,answer:options.indexOf(good),fields:undefined,lessonId:l.id,lessonTitle:l.title};}
function startSession(button){const area=button.dataset.area,mode=button.dataset.mode||'practice',lessonId=button.dataset.lesson||document.querySelector('#session-lesson')?.value;const limit=Number(document.querySelector('#session-size')?.value||10);let questions=[];
 if(area==='vocabulary'&&!lessonId){const option=button.dataset.core?'core':document.querySelector('#session-filter')?.value||'level';let words=selectWords(vocabulary.entries,state.vocab,{limit:mode==='practice'?limit*3:limit,filter:option==='level'?'all':option,level:option==='level'?state.levels[area]:null});if(button.dataset.word){const w=vocabulary.entries.find(x=>x.id===button.dataset.word);words=w?[w]:[];}if(mode==='practice'&&words.length>=4){for(let i=0;i<Math.min(words.length,limit*3);i+=3){const group=words.slice(i,i+3);if(group.length<3||group.some((w,i)=>group.some((other,j)=>i!==j&&meaningsOverlap(w.meaning,other.meaning)))){questions.push(...group.map(w=>vocabularyQuestion(w,vocabulary.entries)));continue;}questions.push(prepareQuestion({id:`match-${group.map(w=>w.id).join('-')}`,kind:'match',prompt:'Relacione cada vocábulo à sua glossa.',pairs:group.map(w=>({left:w.lemma,right:w.meaning})),wordIds:group.map(w=>w.id),explanation:group.map(w=>`${w.lemma}: ${w.meaning}`).join(' · '),label:'Vocabulário'}));}questions=questions.slice(0,limit);}else questions=words.map(w=>vocabularyQuestion(w,vocabulary.entries));
 }else{const sources=lessonId?lessons.filter(l=>l.id===lessonId&&l.area===area):areaLessons(area,state.levels[area]);questions=shuffle(sources.flatMap(l=>l.questions.filter(q=>mode!=='flashcards'||['choice','parse'].includes(q.kind)).map(q=>mode==='flashcards'&&q.kind==='parse'?parsingCard(q,l):prepareQuestion(q,l)))).slice(0,limit);}
 if(!questions.length){toast('Não há exercícios neste filtro. Escolha outro assunto ou repertório.');return;}
 session={area,mode,questions,index:0,correct:0,results:[],answered:false,selected:null,matched:[],matchErrors:[],matchLeft:null,order:[],mistakes:0};searchOpen=false;render();window.scrollTo(0,0);
}
function audioHTML(q){return q.audio&&/^(?:\.\/)?assets\/audio\/[a-zA-Z0-9_./-]+\.(?:mp3|ogg|wav)$/i.test(q.audio)?`<audio controls preload="none" aria-label="Ouvir vocábulo" style="display:block;margin:0 auto 18px;max-width:100%"><source src="${esc(q.audio)}">Seu navegador não oferece reprodução de áudio.</audio>`:'';}
function sessionPage(){if(session.index>=session.questions.length)return resultPage();const q=session.questions[session.index];let exercise='';if(q.kind==='choice')exercise=`<div class="answers">${q.options.map((o,i)=>`<button class="answer ${session.answered?(i===q.answer?'correct':i===session.selected?'wrong':''):''}" data-action="answer" data-index="${i}" ${session.answered?'disabled':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span>${session.answered&&i===q.answer?icon('check',15):''}</button>`).join('')}</div>`;
 else if(q.kind==='parse')exercise=`<div class="parse-grid">${q.fields.map((f,i)=>`<label class="field">${esc(f.label)}<select data-parse-field="${i}" ${session.answered?'disabled':''}><option value="">Selecionar…</option>${f.options.map(o=>`<option value="${esc(o)}" ${(session.parseValues||[])[i]===o?'selected':''}>${esc(o)}</option>`).join('')}</select>${session.answered?`<span style="color:${(session.parseValues||[])[i]===f.answer?'#486839':'#a23535'}">${(session.parseValues||[])[i]===f.answer?'Correto':`Resposta: ${esc(f.answer)}`}</span>`:''}</label>`).join('')}</div>${!session.answered?'<button class="button button-primary" data-action="check-parse">Verificar análise</button>':''}`;
 else if(q.kind==='match')exercise=`<div class="match-grid"><div class="match-column">${q.pairs.map((pair,i)=>`<button ${/[\u0370-\u03ff\u1f00-\u1fff]/.test(pair.left)?'lang="grc"':''} class="match-button left ${session.matched.includes(i)?'matched':session.matchLeft===i?'selected':''}" data-action="match-left" data-index="${i}" ${session.matched.includes(i)||session.answered?'disabled':''} aria-pressed="${session.matchLeft===i}">${esc(pair.left)}</button>`).join('')}</div><div class="match-column">${q.rightOrder.map(i=>`<button class="match-button ${session.matched.includes(i)?'matched':''}" data-action="match-right" data-index="${i}" ${session.matched.includes(i)||session.answered?'disabled':''}>${esc(q.pairs[i].right)}</button>`).join('')}</div></div><p class="muted" style="font-size:10px;margin-top:13px">${session.matchHint||'Selecione um item à esquerda e seu par à direita.'}</p>`;
 else if(q.kind==='order')exercise=`<div class="order-target" aria-label="Sua sequência">${session.order.length?session.order.map((index,position)=>`<button class="token" data-action="order-remove" data-index="${position}" ${session.answered?'disabled':''}>${esc(q.tokens[index])}</button>`).join(''):'<span class="muted" style="font-size:11px">Selecione os blocos na ordem desejada.</span>'}</div><div class="order-options">${q.tokenOrder.filter(i=>!session.order.includes(i)).map(i=>`<button class="token" data-action="order-add" data-index="${i}" ${session.answered?'disabled':''}>${esc(q.tokens[i])}</button>`).join('')}</div>${!session.answered?'<button class="button button-primary" data-action="check-order">Verificar sequência</button>':''}`;
 return shell(`<div class="session-wrap"><div class="session-top"><button class="icon-button" data-action="exit-session" aria-label="Encerrar sessão">${icon('close',15)}</button>${progress(session.index,session.questions.length)}<span>${session.index+1} de ${session.questions.length}</span></div><section class="question-card"><div class="question-meta"><span class="eyebrow">${session.mode==='flashcards'?'Flashcards':'Prática'} · ${AREAS[session.area].name}</span><span class="pill">${esc(q.label||LEVELS[state.levels[session.area]])}</span></div><h2>${esc(q.prompt)}</h2>${q.greek?`<div class="question-greek ${q.greek.length>25?'long':''}" lang="grc">${esc(q.greek)}</div>`:''}${audioHTML(q)}${exercise}${session.answered?`<div class="feedback ${session.lastCorrect?'':'error'}" role="status"><div class="feedback-title">${icon(session.lastCorrect?'check':'info',17)}${session.lastCorrect?'Muito bem. Observe o motivo:':'Vamos rever o conceito.'}</div><p>${esc(q.explanation)}</p>${q.wordIds?`<p>${q.kind==='match'?'Revisões registradas por vocábulo; os acertos foram preservados.':session.lastCorrect?'Acerto registrado. Reencontre estes vocábulos em dias diferentes.':'O vocábulo desta questão volta à revisão.'}</p>`:''}${q.lessonId?`<a class="text-link" href="#/${session.area}/article/${q.lessonId}" style="margin-top:11px">Revisar o artigo${icon('arrow',12)}</a>`:''}</div>`:''}</section><div class="session-actions"><span>${session.answered?'Sua resposta foi registrada neste navegador.':'Sem pressa. Leia, observe e selecione.'}</span>${session.answered?`<button class="button button-primary" data-action="next">${session.index+1===session.questions.length?'Ver resultado':'Continuar'}${icon('arrow',14)}</button>`:''}</div></div>`,session.area,`${AREAS[session.area].name} / ${session.mode==='flashcards'?'Flashcards':'Prática'}`);
}
function finishAnswer(correct,selected=null){if(!session||session.answered)return;const q=session.questions[session.index];session.answered=true;session.lastCorrect=correct;session.selected=selected;if(correct)session.correct++;session.results.push({id:q.id,correct,explanation:q.explanation,lessonTitle:q.lessonTitle});state.answers[q.id]={correct,day:localDate(),attempts:(state.answers[q.id]?.attempts||0)+1};for(const [i,id] of (q.wordIds||[]).entries())state.vocab[id]=reviewAnswer(state.vocab[id],q.kind==='match'?!session.matchErrors.includes(i):correct);save();render();document.querySelector('.feedback')?.scrollIntoView({block:'nearest',behavior:'smooth'});document.querySelector('[data-action=next]')?.focus({preventScroll:true});}
function resultPage(){const errors=session.results.filter(r=>!r.correct);return shell(`<div class="session-wrap"><section class="session-result"><div class="result-glyph" lang="grc">${errors.length?'μελέτη':'καλῶς'}</div><span class="eyebrow">Sessão concluída</span><h1>${errors.length?'Revise os pontos de atenção.':'Sessão concluída.'}</h1><div class="result-count">${session.correct}<span> / ${session.questions.length} acertos</span></div><p>${session.area==='vocabulary'?'Seu histórico de revisão foi atualizado. Volte em dias diferentes para consolidar a memória.':'Use os comentários das questões para decidir o que reler. A leitura e a prática se completam.'}</p>${errors.length?`<div class="session-error-list"><h3>Pontos para reencontrar</h3>${errors.slice(0,5).map(e=>`<p>${e.lessonTitle?`<strong>${esc(e.lessonTitle)}:</strong> `:''}${esc(e.explanation)}</p>`).join('')}</div>`:''}<div class="result-actions">${errors.length?'<button class="button button-primary" data-action="retry-errors">Revisar as questões</button>':''}<button class="button ${errors.length?'button-outline':'button-primary'}" data-action="exit-session">Voltar ao estudo${icon('arrow',13)}</button></div></section></div>`,session.area,`${AREAS[session.area].name} / Resultado`);}

function progressPage(){const allRead=lessons.filter(l=>state.lessons[l.id]).length,totalTokens=tokenCount();return shell(`<div class="page-intro"><div><span class="eyebrow">Acompanhamento do estudo</span><h1>Meu progresso</h1><p>Acompanhe suas leituras e revisões. Os dados ficam somente neste navegador, sem cadastro.</p></div></div><div class="progress-grid"><section class="progress-card"><h3>Leituras concluídas</h3><strong>${allRead}</strong><p>de ${lessons.length} artigos disponíveis</p></section><section class="progress-card"><h3>Vocábulos memorizados</h3><strong>${mastered().length}</strong><p>acertos em pelo menos três dias diferentes</p></section><section class="progress-card"><h3>Cobertura lexical</h3><strong>${pct(coverage(vocabulary.entries,state.vocab,totalTokens))}%</strong><p>ocorrências dos lemas memorizados no corpus</p></section></div><section class="core-box"><div class="core-box-top"><div><span class="eyebrow">Núcleo dos 300</span><h3 style="margin-top:8px">${coreMastered()===300?'Você consolidou os 300 vocábulos prioritários.':'Reencontre as palavras que mais aparecem.'}</h3></div><span class="core-count">${coreMastered()} <span>/ 300</span></span></div>${progress(coreMastered(),300)}<p>Este conjunto representa ${pct(vocabulary.meta.core300?.coveragePercent||0)}% das ocorrências do corpus. É cobertura de vocabulário, não uma medida de compreensão.</p></section><section class="progress-detail"><h2>Suas leituras por área</h2>${Object.entries(AREAS).map(([key,a])=>`<div class="progress-line"><span>${a.name}</span>${progress(completed(key),areaLessons(key).length)}<span>${completed(key)} / ${areaLessons(key).length}</span></div>`).join('')}</section><div class="backup-panel"><div><h3>Leve seu histórico com você</h3><p>Limpar os dados do navegador pode apagar o progresso. Exporte uma cópia e importe-a depois, inclusive em outro aparelho. A importação substitui o histórico deste navegador.</p></div><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="button button-outline button-small" data-action="export">${icon('download',13)}Exportar</button><label class="button button-outline button-small" style="cursor:pointer">Importar<input class="sr-only" type="file" id="import-progress" accept="application/json,.json"></label></div></div>`, 'progress','Meu progresso');}
function aboutPage(){const meta=vocabulary.meta;return shell(`<div class="page-intro"><div><span class="eyebrow">Conhecimento aberto, fontes identificadas</span><h1>Sobre o projeto</h1><p>Um projeto pessoal de Laylson de Albuquerque para tornar o estudo do grego koiné mais acessível e constante.</p></div></div><article class="legal-content"><h2>Aprender a língua, ler com atenção</h2><p>O programa combina reconhecimento de padrões na morfologia, compreensão de relações na sintaxe e memorização no vocabulário. Os quatro níveis são pontos de entrada: o percurso pode ser seguido em ordem ou consultado por assunto.</p><p>O nível avançado apresenta comparações entre abordagens. Uma categoria usada por um autor não deve ser transferida automaticamente para outro. Leituras concluídas e acertos em exercícios ajudam a acompanhar o estudo; não certificam domínio integral da língua.</p><h2>Referências de estudo</h2><ul><li>Stanley E. Porter, Jeffrey T. Reed e Matthew Brook O’Donnell. <em>Fundamentals of New Testament Greek</em>. Eerdmans, 2010. Base prioritária para progressão e morfologia.</li><li>Stanley E. Porter. <em>Idioms of the Greek New Testament</em>. Referência prioritária de sintaxe e abordagem aspectual.</li><li>Daniel B. Wallace. <em>Greek Grammar Beyond the Basics</em> / <em>Gramática Grega: uma sintaxe exegética do Novo Testamento</em>. Complemento identificado e comparação de perspectivas.</li></ul><p>Artigos, exemplos didáticos, glossas em português e exercícios têm redação própria. Os PDFs, suas extrações, suas traduções integrais, exercícios editoriais e imagens de páginas não são distribuídos pelo projeto. Referências não indicam vínculo ou endosso dos autores.</p><h2>De onde vêm o vocabulário e as frequências?</h2><p>O repertório tem ${fmt.format(vocabulary.entries.length)} lemas, ordenados por frequência a partir de dados abertos. A seleção linguística foi conferida com o repertório bibliográfico de <em>Fundamentals</em>, com normalização das variantes lexicais. A organização por frequência e as glossas portuguesas são próprias.</p><p>As frequências foram calculadas sobre ${fmt.format(tokenCount())} ocorrências do SBLGNT na versão do conjunto MACULA registrada no arquivo de dados. O percentual dos 300 prioritários é calculado somando suas ocorrências e dividindo pelo total desse corpus. Ele pode variar conforme a edição e a lematização.</p><div class="notice">${esc(meta.bibliographicAudit?.publicNote||meta.methodology||'Formas variantes e diferenças de lematização entre fontes são registradas nos metadados do repertório. O critério de frequência é independente da organização editorial do livro.')}<br><br>O indicador representa ocorrências de palavras, não a porcentagem de passagens que alguém já consegue interpretar.</div><ul><li><a href="https://www.sblgnt.com/license/" target="_blank" rel="noopener">SBL Greek New Testament</a> — Michael W. Holmes, editor; Society of Biblical Literature e Logos Bible Software. Texto sob CC BY 4.0.</li><li><a href="https://github.com/Clear-Bible/macula-greek" target="_blank" rel="noopener">MACULA Greek Linguistic Datasets</a> — Clear Bible. Lemas e classes gramaticais utilizados sob CC BY 4.0. Frequências e seleção foram calculadas para este projeto. Campos de terceiros com licença não confirmada, como domínios Louw–Nida/MARBLE, não são redistribuídos.</li></ul><h2>Licenças e reutilização</h2><p>O código está disponível sob a <a href="./LICENSE" target="_blank">licença MIT</a>. Os materiais didáticos originais e os dados derivados identificados estão sob <a href="https://creativecommons.org/licenses/by/4.0/deed.pt-br" target="_blank" rel="noopener">CC BY 4.0</a>, preservadas as atribuições das fontes. Você pode compartilhar e adaptar, inclusive para uso comercial, respeitando os créditos e a indicação de alterações.</p><p>As fontes Encode Sans, Manrope e GFS Didot são distribuídas sob SIL Open Font License; os avisos acompanham os arquivos em assets. Veja todos os créditos e condições em <a href="./THIRD_PARTY_NOTICES.md" target="_blank">THIRD_PARTY_NOTICES.md</a>.</p><h2>Seu progresso e sua privacidade</h2><p>Não há contas, anúncios, ferramentas de análise de visitantes nem envio do histórico de respostas. Os dados de estudo são salvos no armazenamento local do seu navegador. O GitHub Pages fornece a hospedagem e pode processar os dados técnicos usuais de acesso conforme sua própria política.</p><p>Use a exportação em “Meu progresso” para preservar uma cópia. O sistema registra um vocábulo como memorizado após acertos em três dias diferentes; um erro o devolve à revisão. Esse é um critério de acompanhamento do estudo.</p><h2>Pronúncia e áudio</h2><p>A orientação escrita de pronúncia segue a convenção erasmiana adotada pelo curso. O site aceita gravações por vocábulo quando houver um campo audio no repertório. Não há cobrança de serviço de áudio: gravações próprias ou autorizadas podem ser hospedadas junto ao site. Nenhuma voz moderna do navegador é apresentada como pronúncia erasmiana.</p></article>`, 'about','Sobre o projeto');}

function render(){let html;const r=route();if(session)html=sessionPage();else if(AREAS[r[0]])html=r[1]==='article'?articlePage(r[0],r[2]):areaPage(r[0],['path','articles','flashcards','practice','words'].includes(r[1])?r[1]:'path');else if(r[0]==='progress')html=progressPage();else if(r[0]==='about')html=aboutPage();else html=home();app.innerHTML=html;mountHomeMotion();document.title=`${session?'Estudando':AREAS[r[0]]?.name||({progress:'Meu progresso',about:'Sobre o projeto'})[r[0]]||'Seu espaço de estudo'} · Koiné`;if(searchOpen)renderSearch();}
function renderSearch(){document.querySelector('.search-overlay')?.remove();const el=document.createElement('div');el.className='search-overlay';el.innerHTML=`<section class="search-dialog" role="dialog" aria-modal="true" aria-label="Buscar no conteúdo"><div class="search-dialog-top"><label class="search-field">${icon('search',17)}<span class="sr-only">Buscar em artigos e vocabulário</span><input id="global-search" type="search" value="${esc(searchTerm)}" placeholder="Um conceito, uma palavra, uma dúvida…" autocomplete="off"></label><button class="icon-button" data-action="close-search" aria-label="Fechar busca">${icon('close',17)}</button></div><div id="search-results">${searchResults()}</div></section>`;document.body.append(el);el.querySelector('input').focus();}
function searchResults(){const query=normalize(searchTerm.trim());if(query.length<2)return '<p class="muted" style="font-size:11px">Digite pelo menos duas letras. Busque em português ou grego, com ou sem acentos.</p>';const found=lessons.filter(l=>normalize(`${l.title} ${l.summary} ${l.sections.map(s=>s.body).join(' ')}`).includes(query)).slice(0,10);const words=vocabulary.entries.filter(w=>normalize(`${w.lemma} ${w.meaning} ${(w.aliases||[]).join(' ')}`).includes(query)).slice(0,8);return `<div class="search-results">${found.map(l=>`<a class="search-result" href="#/${l.area}/article/${l.id}">${esc(l.title)}<span>${AREAS[l.area].name} · ${LEVELS[l.level]}</span></a>`).join('')}${words.map(w=>`<button class="search-result" data-action="search-word" data-word="${w.id}"><strong class="greek" lang="grc">${esc(w.lemma)}</strong><span>${esc(w.meaning)}</span></button>`).join('')}${!found.length&&!words.length?'<p class="muted" style="font-size:11px">Nenhum resultado. Tente um termo mais curto.</p>':''}</div>`;}

document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button){if(event.target.classList.contains('search-overlay'))closeSearch();if(event.target.closest('a[href^="#/"]')){session=null;searchOpen=false;document.querySelector('.search-overlay')?.remove();menuOpen=false;}return;}
 const action=button.dataset.action;
 if(action==='theme'){const value=toggleTheme();const label=value==='dark'?'Ativar modo claro':'Ativar modo noturno';document.querySelectorAll('[data-action="theme"]').forEach(el=>{el.innerHTML=icon(value==='dark'?'sun':'moon',19);el.setAttribute('aria-label',label);el.title=label;});}
 if(action==='explore')document.getElementById('formacoes')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
 if(action==='close-menu'){menuOpen=false;render();document.querySelector('.menu-toggle')?.focus();}
 if(action==='menu'){menuOpen=!menuOpen;render();document.querySelector('.menu-toggle')?.focus();}
 if(action==='level'){state.levels[button.dataset.area]=Number(button.dataset.level);save();render();}
 if(action==='read'){state.lessons[button.dataset.lesson]=!state.lessons[button.dataset.lesson];save();render();toast(state.lessons[button.dataset.lesson]?'Leitura concluída. Pratique para aplicar o conceito.':'A leitura voltou a ficar em aberto.');}
 if(action==='search'){searchOpen=true;searchTerm='';renderSearch();}
 if(action==='close-search')closeSearch();
 if(action==='start')startSession(button);
 if(action==='word'){const synthetic={dataset:{area:'vocabulary',mode:'flashcards',word:button.dataset.word}};startSession(synthetic);}
 if(action==='search-word'){closeSearch();startSession({dataset:{area:'vocabulary',mode:'flashcards',word:button.dataset.word}});}
 if(action==='page'){vocabPage=Number(button.dataset.page);document.querySelector('#word-results').innerHTML=wordResults();document.querySelector('.vocab-toolbar').scrollIntoView({block:'start'});}
 if(action==='answer')finishAnswer(Number(button.dataset.index)===session.questions[session.index].answer,Number(button.dataset.index));
 if(action==='check-parse'){const q=session.questions[session.index];const values=[...document.querySelectorAll('[data-parse-field]')].map(s=>s.value);if(values.some(v=>!v)){toast('Selecione uma resposta em cada campo.');return;}session.parseValues=values;finishAnswer(q.fields.every((f,i)=>values[i]===f.answer));}
 if(action==='match-left'&&!session.answered){session.matchLeft=Number(button.dataset.index);session.matchHint='Agora selecione o par correspondente à direita.';render();}
 if(action==='match-right'&&!session.answered){if(session.matchLeft===null){toast('Selecione primeiro um item à esquerda.');return;}const right=Number(button.dataset.index);if(right===session.matchLeft){session.matched.push(right);session.matchLeft=null;session.matchHint='Par correto. Continue com os demais.';if(session.matched.length===session.questions[session.index].pairs.length)finishAnswer(session.mistakes===0);else render();}else{session.mistakes++;session.matchErrors.push(session.matchLeft);session.matchHint='Esse par não corresponde. Observe as pistas e tente novamente.';render();}}
 if(action==='order-add'&&!session.answered){session.order.push(Number(button.dataset.index));render();}
 if(action==='order-remove'&&!session.answered){session.order.splice(Number(button.dataset.index),1);render();}
 if(action==='check-order'){const q=session.questions[session.index];if(session.order.length!==q.tokens.length){toast('Use todos os blocos antes de verificar.');return;}finishAnswer(session.order.map(i=>q.tokens[i]).join('\u0001')===q.answer.join('\u0001'));}
 if(action==='next'){session.index++;session.answered=false;session.selected=null;session.matched=[];session.matchErrors=[];session.matchLeft=null;session.matchHint='';session.mistakes=0;session.order=[];session.parseValues=[];if(session.index===session.questions.length){state.sessions++;save();}render();window.scrollTo(0,0);}
 if(action==='exit-session'){const previous=session;session=null;goto(`${previous.area}/${previous.mode}`);}
 if(action==='retry-errors'){const failed=new Set(session.results.filter(r=>!r.correct).map(r=>r.id));session={...session,questions:session.questions.filter(q=>failed.has(q.id)),index:0,correct:0,results:[],answered:false,selected:null,matched:[],matchErrors:[],matchLeft:null,order:[],mistakes:0,parseValues:[]};render();}
 if(action==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`koine-progresso-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
function closeSearch(){searchOpen=false;document.querySelector('.search-overlay')?.remove();document.querySelector('[data-action="search"]')?.focus();}
document.addEventListener('input',event=>{if(event.target.id==='vocab-search'){vocabSearch=event.target.value;vocabPage=0;document.querySelector('#word-results').innerHTML=wordResults();}if(event.target.id==='global-search'){searchTerm=event.target.value;document.querySelector('#search-results').innerHTML=searchResults();}});
document.addEventListener('change',async event=>{if(event.target.id==='vocab-filter'||event.target.id==='vocab-class'){vocabFilter=document.querySelector('#vocab-filter').value;vocabClass=document.querySelector('#vocab-class').value;vocabPage=0;document.querySelector('#word-results').innerHTML=wordResults();}if(event.target.id==='import-progress'){try{const file=event.target.files[0];if(!file)return;if(file.size>4_000_000)throw Error('Arquivo muito grande.');const data=JSON.parse(await file.text());if(!validProgress(data))throw Error('Este arquivo não contém um histórico válido do Koiné.');if(!confirm('Importar este arquivo substituirá o progresso salvo neste navegador. Continuar?'))return;state={...blank(),...data};save();render();toast('Seu histórico foi importado.');}catch(error){toast(error.message||'Não foi possível importar o arquivo.');}}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&searchOpen)closeSearch();else if(event.key==='Escape'&&menuOpen){menuOpen=false;render();document.querySelector('.menu-toggle')?.focus();}if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();searchOpen=true;searchTerm='';renderSearch();}if(event.key==='Tab'&&searchOpen){const controls=[...document.querySelector('.search-dialog').querySelectorAll('button,a,input')];const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{session=null;searchOpen=false;menuOpen=false;document.querySelector('.search-overlay')?.remove();render();window.scrollTo(0,0);});
try{const [m,s,v,w]=await Promise.all(['morphology','syntax','vocabulary-lessons','vocabulary'].map(async name=>{const response=await fetch(`./data/${name}.json`);if(!response.ok)throw Error(`Não foi possível carregar ${name}.`);return response.json();}));lessons=[...m,...s,...v];vocabulary=w;render();}catch(error){app.innerHTML=`<main class="loading"><span class="brand-mark">κ.</span><h1 style="font-size:32px">O estudo ainda não abriu.</h1><p>${esc(error.message)} Recarregue a página ou confira a conexão.</p><button class="button button-primary" onclick="location.reload()">Tentar novamente</button></main>`;}
